/**
 * Test file for Inbound Email trigger with hidden inputs
 *
 * Hidden inputs (should NOT appear in user code):
 * - order (IntegerColumn with visible: false, default: 100)
 * - stop_condition_evaluation (BooleanColumn with visible: false, default: true)
 *
 * Visible inputs (should appear in user code):
 * - email_conditions (StringColumn)
 * - target_table (TableNameColumn)
 */

import { Flow, wfa, trigger, action } from '@servicenow/sdk/automation'

Flow(
    {
        $id: Now.ID['flow_inbound_email_hidden_test'],
        name: 'Inbound Email Hidden Inputs Test',
        description: 'Tests Inbound Email trigger with hidden inputs',
        runAs: 'system',
    },
    wfa.trigger(
        trigger.application.inboundEmail,
        { $id: Now.ID['trigger_inbound_email'] },
        {
            email_conditions: 'subject CONTAINS test',
            target_table: 'incident',
            // order: NOT HERE - hidden input
            // stop_condition_evaluation: NOT HERE - hidden input
        }
    ),
    (_params) => {
        wfa.action(
            action.core.log,
            {
                $id: Now.ID['action_log_email'],
                annotation: 'Log email received',
            },
            {
                log_level: 'info',
                log_message: 'Email received',
            }
        )
    }
)
